package com.alibaba.fastjson2.util;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONException;
import com.alibaba.fastjson2.JSONFactory;
import com.alibaba.fastjson2.JSONObject;
import com.alibaba.fastjson2.reader.ObjectReaderProvider;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Constructor;
import java.math.BigDecimal;
import java.util.function.Function;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test for TypeUtils.cast method with org.bson.types.Decimal128 to Double conversion.
 * This test verifies the fix for issue #2558.
 */
public class TypeUtilsDecimal128Test {

    /**
     * Test that org.bson.types.Decimal128 can be cast to Double.
     * Since we cannot directly depend on org.bson.types.Decimal128 in the test,
     * we simulate the scenario using reflection to create a Decimal128 instance.
     */
    @Test
    public void testCastDecimal128ToDouble() throws Exception {
        // Try to load Decimal128 class dynamically
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            // If Decimal128 is not in classpath, skip the test
            System.out.println("org.bson.types.Decimal128 not found, skipping test");
            return;
        }

        // Create a Decimal128 instance equivalent to 123.456
        // Decimal128 has a constructor taking BigDecimal
        Constructor<?> constructor = decimal128Class.getConstructor(BigDecimal.class);
        Object decimal128 = constructor.newInstance(new BigDecimal("123.456"));

        // Perform the cast
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();
        Double result = TypeUtils.cast(decimal128, Double.class, provider);

        // Verify the result
        assertNotNull(result);
        assertEquals(123.456, result, 0.0001);
    }

    /**
     * Test that the cast works when Decimal128 is wrapped in a JSONObject.
     * This simulates the real-world scenario described in the issue.
     */
    @Test
    public void testDecimal128InJSONObjectToJavaObject() throws Exception {
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            System.out.println("org.bson.types.Decimal128 not found, skipping test");
            return;
        }

        // Create a Decimal128 instance
        Constructor<?> constructor = decimal128Class.getConstructor(BigDecimal.class);
        Object decimal128 = constructor.newInstance(new BigDecimal("99.99"));

        // Create a JSONObject and put the Decimal128 as a value
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("value", decimal128);

        // Convert to a Java object with Double field
        ValueHolder holder = jsonObject.toJavaObject(ValueHolder.class);
        assertNotNull(holder);
        assertEquals(99.99, holder.value, 0.0001);
    }

    /**
     * Test that other conversions are not affected by the new code.
     */
    @Test
    public void testOtherCastsStillWork() {
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Integer to Double
        Double d1 = TypeUtils.cast(100, Double.class, provider);
        assertEquals(100.0, d1);

        // String to Double
        Double d2 = TypeUtils.cast("3.14", Double.class, provider);
        assertEquals(3.14, d2);

        // BigDecimal to Double
        Double d3 = TypeUtils.cast(new BigDecimal("2.718"), Double.class, provider);
        assertEquals(2.718, d3);
    }

    /**
     * Test that non-Decimal128 objects still throw appropriate exceptions when cannot cast.
     */
    @Test
    public void testInvalidCastThrows() {
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();
        // Trying to cast a non-numeric object to Double should throw
        assertThrows(JSONException.class, () -> {
            TypeUtils.cast(new Object(), Double.class, provider);
        });
    }

    /**
     * Helper class for testing JSONObject.toJavaObject conversion.
     */
    public static class ValueHolder {
        private Double value;

        public Double getValue() {
            return value;
        }

        public void setValue(Double value) {
            this.value = value;
        }
    }
}

